print("Input -> Output")
for i in range(len(inputs)):
    print(f"{inputs[i]} -> {outputs[i]}")

print("\nLet me examine character positions:")
for i in range(len(inputs)):
    inp = inputs[i]
    out = outputs[i]
    print(f"\n{inp} -> {out}")
    if inp != out:
        # Find where they differ
        min_len = min(len(inp), len(out))
        for j in range(min_len):
            if inp[j] != out[j]:
                print(f"  First difference at position {j}: '{inp[j]}' -> '{out[j]}'")
                break
        else:
            if len(inp) != len(out):
                print(f"  Length changed: {len(inp)} -> {len(out)}")

